begin;
create table if not exists public.mme_vendor_catalog_items(catalog_item_id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.mme_financial_vendors(vendor_id) on delete restrict,vendor_sku text not null,inventory_item_id uuid references public.mme_inventory_items(inventory_item_id),vendor_product_name text not null,brand text,manufacturer_part_number text,product_url text,active boolean not null default true,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(vendor_id,vendor_sku));
create table if not exists public.mme_vendor_catalog_offers(offer_id uuid primary key default gen_random_uuid(),catalog_item_id uuid not null references public.mme_vendor_catalog_items(catalog_item_id) on delete restrict,unit_cost numeric(16,4) not null check(unit_cost>=0),currency_code char(3) not null default 'USD',minimum_order_quantity numeric(14,3) not null default 1 check(minimum_order_quantity>0),available_quantity numeric(14,3) check(available_quantity is null or available_quantity>=0),lead_time_days integer check(lead_time_days is null or lead_time_days>=0),valid_from date not null default current_date,valid_until date,offer_status text not null default 'active' check(offer_status in('active','expired','withdrawn')),source_reference text,verified_at timestamptz,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(valid_until is null or valid_until>=valid_from));
create index if not exists mme_vendor_catalog_vendor_idx on public.mme_vendor_catalog_items(vendor_id,active,vendor_sku);
create index if not exists mme_vendor_catalog_inventory_idx on public.mme_vendor_catalog_items(inventory_item_id) where inventory_item_id is not null;
create index if not exists mme_vendor_catalog_offers_current_idx on public.mme_vendor_catalog_offers(catalog_item_id,offer_status,valid_from,valid_until);
create table if not exists public.mme_vendor_quote_lines(quote_line_id uuid primary key default gen_random_uuid(),quote_id uuid not null references public.mme_vendor_quotes(quote_id) on delete restrict,inventory_item_id uuid references public.mme_inventory_items(inventory_item_id),description text not null,quantity numeric(14,3) not null check(quantity>0),unit_cost numeric(16,4) not null check(unit_cost>=0),currency_code char(3) not null default 'USD',lead_time_days integer check(lead_time_days is null or lead_time_days>=0),availability_note text,created_at timestamptz not null default now());
create index if not exists mme_vendor_quote_lines_quote_idx on public.mme_vendor_quote_lines(quote_id);
do $$declare t text;begin foreach t in array array['mme_vendor_catalog_items','mme_vendor_catalog_offers','mme_vendor_quote_lines'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
commit;